import { describe, it, expect, beforeAll, afterEach, afterAll, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw/http';
import { GET } from '../web/next/app/api/slots/route.js';

const API = 'http://labflow-api.test';
const ALL = [
  { id: 1, lab: 'BE-201', date: '2026-11-16', start: '07:00', end: '09:00', seats: 20, status: 'CONFIRMED', minutes: 120 },
  { id: 2, lab: 'BE-201', date: '2026-11-16', start: '10:00', end: '20:30', seats: 20, status: 'CONFIRMED', minutes: 630 },
  { id: 3, lab: 'BE-305', date: '2026-11-16', start: '09:00', end: '10:00', seats: 20, status: 'CONFIRMED', minutes: 60 },
];
const server = setupServer(http.get(API + '/api/admin/bookings', () => HttpResponse.json(ALL)));
beforeAll(() => server.listen({ onUnhandledFrame: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

// Starter: ONE smoke test — it only checks that the code under test can be imported. It kills no mutant.
// Write the real tests below (see the task). Khởi đầu: MỘT test khói — chỉ kiểm code nạp được, không diệt đột biến nào.
describe('starter', () => {
  it('the code under test can be imported', () => {
    expect(GET).toBeDefined();
  });
});

import { parseTime } from './time.js';

export const OPEN = 7 * 60;          // 07:00
export const CLOSE = 21 * 60;        // 21:00
export const STEP = 30;              // BR-04: 30-minute grid
export const MAX_MINUTES = 240;      // Lite-1: at most 4 hours
export const MAX_DAYS_AHEAD = 14;    // BR-05: at most 14 days ahead
export const APPROVAL_SEATS = 30;    // BR-06: more than 30 seats needs approval

export function checkSlot(start, end) {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % STEP !== 0 || e % STEP !== 0) return { ok: false, code: 'OFF_GRID' };
  if (e <= s) return { ok: false, code: 'END_BEFORE_START' };
  if (s < OPEN || e > CLOSE) return { ok: false, code: 'OUTSIDE_HOURS' };
  if (e - s > MAX_MINUTES) return { ok: false, code: 'TOO_LONG' };
  return { ok: true, minutes: e - s };
}

export function isWithinBookingWindow(daysAhead) {
  return Number.isInteger(daysAhead) && daysAhead >= 0 && daysAhead <= MAX_DAYS_AHEAD;
}

export function needsApproval({ seats, role }) {
  if (!Number.isInteger(seats) || seats < 1) {
    throw new RangeError('seats must be a positive integer, got ' + seats);
  }
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > APPROVAL_SEATS;
}

export function createBooking({ lab, seats, role, start, end }) {
  const slot = checkSlot(start, end);
  if (!slot.ok) throw new Error(slot.code);
  return {
    lab,
    start,
    end,
    minutes: slot.minutes,
    status: needsApproval({ seats, role }) ? 'PENDING' : 'CONFIRMED',
  };
}

// Share of opening hours already booked, added booking by booking (0..1).
export function usageRate(bookings) {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / (CLOSE - OPEN);
  return rate;
}

// Convert between "HH:MM" and minutes since 00:00.
export function parseTime(text) {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) throw new RangeError('Time out of range: ' + text);
  return h * 60 + min;
}

export function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

// GET /api/slots?lab=BE-201&date=2026-11-16 — a Next.js route handler is a function from Request to Response.
import { listBookings } from '../../../lib/bookings.js';
import { freeSlots } from '../../../lib/slots.js';

export async function GET(request) {
  const { searchParams } = new URL(request.url);
  const lab = searchParams.get('lab');
  const date = searchParams.get('date');
  if (!lab || !date) return Response.json({ error: { code: 'VALIDATION' } }, { status: 400 });
  try {
    return Response.json({ lab, date, free: freeSlots(await listBookings({ lab, date })) });
  } catch {
    return Response.json({ error: { code: 'UPSTREAM_DOWN' } }, { status: 502 });
  }
}

// Server-side data access for the Next.js app: it calls the LabFlow Lite API with a service token.
const api = (path) => fetch(process.env.LABFLOW_API_URL + path, {
  headers: { Authorization: 'Bearer ' + process.env.LABFLOW_SERVICE_TOKEN },
});

export async function listBookings({ lab, date }) {
  const res = await api('/api/admin/bookings');
  if (!res.ok) throw new Error('LabFlow API answered ' + res.status);
  return (await res.json()).filter((b) => b.lab === lab && b.date === date);
}

export async function getBooking(id) {
  const res = await api('/api/bookings/' + encodeURIComponent(id));
  if (res.status === 404) return null;
  if (!res.ok) throw new Error('LabFlow API answered ' + res.status);
  return res.json();
}

// Free half-hour slots of one lab on one day, given that day's bookings. A pure function: unit-test it.
import { OPEN, CLOSE, STEP } from '../../../src/rules/booking.js';
import { parseTime, formatTime } from '../../../src/rules/time.js';

export function freeSlots(bookings) {
  const taken = bookings.map((b) => [parseTime(b.start), parseTime(b.end)]);
  const free = [];
  for (let t = OPEN; t < CLOSE; t += STEP) {
    const busy = taken.some(([start, end]) => t < end && t + STEP > start);
    if (!busy) free.push(formatTime(t));
  }
  return free;
}

